from wordle.game import Game
import sys


def main() -> None:
    play_game()


def play_game(target: Optional[str] = None) -> None:
    game = Game(target)
    display_welcome()
    while True:
        try:
            guess = get_user_input()
            game.make_guess(guess)
            display_game_state(game)
            if game.get_status().value == "won":
                display_result(game)
                break
        except InvalidGuessError as e:
            handle_guess_error(e)
        except GameOverError:
            display_result(game)
            break
    if ask_play_again():
        play_game()


def get_user_input() -> str:
    return input("Enter your guess: ")


def display_welcome() -> None:
    print("Welcome to Wordle! Type 'quit' to stop playing.")


def display_game_state(game: Game) -> None:
    print("Game state:")
    print("Attempts remaining:", game.get_attempts_remaining())
    for result in game.get_results():
        print("Guess:", result.guess)
        for feedback in result.feedbacks:
            print("Feedback:", feedback.value)


def display_result(game: Game) -> None:
    print("Game over. The target word was:", game.get_target_word())


def handle_guess_error(error: Exception) -> None:
    print("Invalid guess:", str(error))


def ask_play_again() -> bool:
    response = input("Do you want to play again? (y/n): ")
    return response.lower() == "y"

